// Load context
let gb = flow.get("gb") || [];                       // array of broker names
let brokerCounters = flow.get("brokerCounters") || {};  // object: { brokerName: count }
let topic = flow.get("topic");
let sensorid = flow.get("sensorid");

// Safety check
if (!Array.isArray(gb)) {
    node.error("gb must be an array");
    return null;
}

// Emit one message per broker
gb.forEach(brokerName => {
    let count = brokerCounters[brokerName] || 0;

    let out = {
        payload: {
            op: "set",
            labels: {
                centre_id: brokerName,
                report_by: sensorid,
                topic: topic
            },
            val: count
        }
    };

    node.send(out);
});

